package com.fittrack.nutrition;
import java.util.*;import java.time.*;import java.math.BigDecimal;import com.fittrack.meal.MealController;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.bind.annotation.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.transaction.annotation.Transactional;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/api/v1") public class NutritionController {
final JdbcTemplate db;final MealController meals;public NutritionController(JdbcTemplate d,MealController m){db=d;meals=m;}
public record Goals(@DecimalMin("0") @DecimalMax("20000") BigDecimal calories,@DecimalMin("0") @DecimalMax("2000") BigDecimal protein,@DecimalMin("0") @DecimalMax("2000") BigDecimal carbs,@DecimalMin("0") @DecimalMax("2000") BigDecimal fat){}
@GetMapping("/nutrition/goals") public Object goals(@AuthenticationPrincipal Jwt j){var rows=db.queryForList("SELECT calories,protein,carbs,fat FROM nutrition_goals WHERE user_id=?",UUID.fromString(j.getSubject()));if(!rows.isEmpty())return rows.get(0);Map<String,Object> empty=new LinkedHashMap<>();for(String k:List.of("calories","protein","carbs","fat"))empty.put(k,null);return empty;}
@PutMapping("/nutrition/goals") @Transactional public Object set(@AuthenticationPrincipal Jwt j,@Valid @RequestBody Goals g){db.update("INSERT INTO nutrition_goals(user_id,calories,protein,carbs,fat) VALUES(?,?,?,?,?) ON CONFLICT(user_id) DO UPDATE SET calories=EXCLUDED.calories,protein=EXCLUDED.protein,carbs=EXCLUDED.carbs,fat=EXCLUDED.fat",UUID.fromString(j.getSubject()),g.calories(),g.protein(),g.carbs(),g.fat());return goals(j);}
@GetMapping("/nutrition/summary") public Object summary(@AuthenticationPrincipal Jwt j,@RequestParam LocalDate date,@RequestParam(defaultValue="Asia/Kolkata") String zone)throws Exception{return Map.of("date",date,"zone",zone,"nutrients",meals.dailyFor(UUID.fromString(j.getSubject()),date,zone).get("summary"),"goals",goals(j));}
@GetMapping("/reports/weekly") public Object weekly(@AuthenticationPrincipal Jwt j,@RequestParam LocalDate start,@RequestParam(defaultValue="Asia/Kolkata") String zone)throws Exception{List<Object> days=new ArrayList<>();for(int i=0;i<7;i++){LocalDate d=start.plusDays(i);days.add(Map.of("date",d,"summary",meals.dailyFor(UUID.fromString(j.getSubject()),d,zone).get("summary")));}return Map.of("start",start,"zone",zone,"days",days);}
public record Ingredient(@NotBlank String foodId,@NotNull @DecimalMin("0.1") @DecimalMax("5000") BigDecimal grams){}
public record Recipe(@NotEmpty @Size(max=100) List<@Valid Ingredient> ingredients,@Min(1) @Max(100) int servings){}
@PostMapping("/recipes/calculate") public Object recipe(@Valid @RequestBody Recipe r){List<Map<String,Object>> values=new ArrayList<>();List<Object> sources=new ArrayList<>();for(var i:r.ingredients()){var rows=db.queryForList("SELECT * FROM foods WHERE id=?",i.foodId());if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Unknown ingredient");var food=rows.get(0);values.add(Nutrition.calculate(food,i.grams()));sources.add(Map.of("foodId",i.foodId(),"grams",i.grams(),"source",food.get("source"),"sourceUrl",food.get("source_url"),"sourceVersion",food.get("source_version")));}var totals=Nutrition.total(values);Map<String,Object> per=new LinkedHashMap<>();for(var key:Nutrition.KEYS){var v=(Map<?,?>)totals.get(key);Object total=v.get("total");per.put(key,total==null?null:new BigDecimal(total.toString()).divide(BigDecimal.valueOf(r.servings()),12,java.math.RoundingMode.HALF_UP));}return Map.of("totals",totals,"perServing",per,"servings",r.servings(),"ingredients",sources,"method","ingredient masses divided into equal portions; no inferred cooked yield");}
}
